# PS6 report: the stylized facts of simulated markets next to daily SPY. Students do not edit this file.
#
# `write_report`, at the end of this file, runs the market with your functions and writes the tables
# of Report.md. A table that needs a function you have not finished shows UNAVAILABLE, and the other
# tables still print.
#
# The file reads from top to bottom:
#   1. Rows
#   2. Tables
#   3. Writing the report

# --- 1. Rows ------------------------------------------------------------------------------------

"""
    market_row(settings, label, rule, K, p; value_number, trend_number) -> NamedTuple

Simulate one market for every run number in `settings.seeds` and average the facts over the runs.

### Arguments

- `settings`: The settings from `load_config`.
- `label`: The name of the row.
- `rule`: `:three` or `:conviction`.
- `K`: The top rung.
- `p`: The probability that a trader acts on a proposed move.
- `value_number`: The number of value investors.
- `trend_number`: The number of trend followers.

### Returns

- A `NamedTuple` with `label`, `kurtosis`, `clustering_short`, `clustering_long`, `lag_one`,
  `volatility`, and `gap_spread`, each a mean over the runs.
"""
function market_row(settings::NamedTuple, label::String, rule::Symbol, K::Int, p::Float64;
    value_number::Int, trend_number::Int)::NamedTuple

    # Sums of each fact over the runs -
    total = (kurtosis = 0.0, clustering_short = 0.0, clustering_long = 0.0,
        lag_one = 0.0, volatility = 0.0, gap_spread = 0.0);

    # One simulated market per run number -
    for seed in settings.seeds

        # Draw the traders, run the market, and summarize the growth rates -
        model = build_market(settings, seed; value_number = value_number, trend_number = trend_number);
        run = simulate_market(model, rule, K, p; number_of_steps = settings.number_of_steps,
            burn_in = settings.burn_in, seed = seed);
        g = growth_rates(run.log_price, settings.Δt);
        gap = run.log_price .- run.log_value;
        facts = market_facts(g, gap, settings);

        # Add the facts of this run to the sums -
        total = (kurtosis = total.kurtosis + facts.kurtosis,
            clustering_short = total.clustering_short + facts.clustering_short,
            clustering_long = total.clustering_long + facts.clustering_long,
            lag_one = total.lag_one + facts.lag_one,
            volatility = total.volatility + facts.volatility,
            gap_spread = total.gap_spread + facts.gap_spread);
    end

    # The mean over the runs -
    runs = length(settings.seeds);
    return (label = label, kurtosis = total.kurtosis / runs,
        clustering_short = total.clustering_short / runs, clustering_long = total.clustering_long / runs,
        lag_one = total.lag_one / runs, volatility = total.volatility / runs,
        gap_spread = total.gap_spread / runs);
end

"""
    benchmark_row(settings) -> NamedTuple

Compute the facts of the daily closes of the benchmark ticker. The `gap_spread` is `NaN`, because
the benchmark has no value.
"""
function benchmark_row(settings::NamedTuple)::NamedTuple

    # The growth rates of the benchmark, and its facts without a gap -
    g = benchmark_growth_rates(settings);
    facts = market_facts(g, zeros(length(g)), settings);

    # The label names the ticker -
    return (label = "$(settings.benchmark_ticker) (daily closes)", kurtosis = facts.kurtosis,
        clustering_short = facts.clustering_short, clustering_long = facts.clustering_long,
        lag_one = facts.lag_one, volatility = facts.volatility, gap_spread = NaN);
end

"""
    probability_text(p::Float64) -> String

Write a probability without trailing zeros, such as `1`, `0.5`, or `0.2`.
"""
function probability_text(p::Float64)::String
    return @sprintf("%g", p);
end

# --- 2. Tables ----------------------------------------------------------------------------------

"""
    problem_text(caught) -> String

Return `UNAVAILABLE: ` and the first line of the message of an error, so that a table can show why
it could not run.
"""
function problem_text(caught)::String

    # The first non-empty line of the message -
    first_line = "";
    for line in split(sprint(showerror, caught), '\n')
        cleaned = Base.strip(line);
        if isempty(first_line) && !isempty(cleaned)
            first_line = String(cleaned);
        end
    end

    # Use the type of the error when the message is empty -
    if isempty(first_line)
        first_line = string(typeof(caught));
    end
    return "UNAVAILABLE: " * first_line;
end

"""
    standard_table(settings) -> Union{Vector{NamedTuple}, String}

Rows of the table "Farmer–Joshi and SPY": the benchmark, value investors only, trend followers only,
and both groups with 3 states. Returns `"UNAVAILABLE: ..."` when a function throws.
"""
function standard_table(settings::NamedTuple)::Union{Vector{NamedTuple},String}
    try
        # The benchmark row -
        rows = NamedTuple[];
        push!(rows, benchmark_row(settings));

        # The three markets of the three-state rule: each group alone, then both groups -
        push!(rows, market_row(settings, "value investors only", :three, 1, 1.0;
            value_number = settings.value_number, trend_number = 0));
        push!(rows, market_row(settings, "trend followers only", :three, 1, 1.0;
            value_number = 0, trend_number = settings.trend_number));
        push!(rows, market_row(settings, "both groups", :three, 1, 1.0;
            value_number = settings.value_number, trend_number = settings.trend_number));
        return rows;
    catch caught
        return problem_text(caught);
    end
end

"""
    ladder_table(settings) -> Union{Vector{NamedTuple}, String}

Rows of the table "Conviction ladders": the benchmark, and both groups for each number of states in
`settings.number_of_states`. Returns `"UNAVAILABLE: ..."` when a function throws.
"""
function ladder_table(settings::NamedTuple)::Union{Vector{NamedTuple},String}
    try
        rows = NamedTuple[];
        push!(rows, benchmark_row(settings));

        # One row for each number of states; n states have the top rung K = (n - 1) / 2 -
        for n in settings.number_of_states
            K = (n - 1) ÷ 2;
            push!(rows, market_row(settings, "both groups, $(n) states", :conviction, K, 1.0;
                value_number = settings.value_number, trend_number = settings.trend_number));
        end
        return rows;
    catch caught
        return problem_text(caught);
    end
end

"""
    hesitant_table(settings) -> Union{Vector{NamedTuple}, String}

Rows of the table "Hesitant traders": the benchmark, and both groups with `settings.expert_states`
states for each probability in `settings.probabilities`. Each row also has `steps`, the expected
number of steps from flat to long. Returns `"UNAVAILABLE: ..."` when a function throws.
"""
function hesitant_table(settings::NamedTuple)::Union{Vector{NamedTuple},String}
    try
        rows = NamedTuple[];
        benchmark = benchmark_row(settings);
        push!(rows, merge(benchmark, (steps = NaN,)));

        # One row for each probability -
        K = (settings.expert_states - 1) ÷ 2;
        for p in settings.probabilities
            label = "$(settings.expert_states) states, p = $(probability_text(p))";
            row = market_row(settings, label, :conviction, K, p;
                value_number = settings.value_number, trend_number = settings.trend_number);

            # The expected steps from flat to long, from the transition matrix -
            P = transition_matrix(10.0, 1.0, -0.1, K, p);
            push!(rows, merge(row, (steps = expected_steps_to_long(P, K),)));
        end
        return rows;
    catch caught
        return problem_text(caught);
    end
end

# --- 3. Writing the report ----------------------------------------------------------------------

"""
    number_text(x::Float64, digits::Int) -> String

Write a number with `digits` decimals (`1`, `2`, or `3`), or `n/a` when the number is `NaN`.
"""
function number_text(x::Float64, digits::Int)::String

    # A missing number prints as n/a -
    if isnan(x)
        return "n/a";
    end

    # Round to the requested number of decimals -
    if digits == 1
        return @sprintf("%.1f", x);
    end
    if digits == 2
        return @sprintf("%.2f", x);
    end
    return @sprintf("%.3f", x);
end

"""
    lag_range_text(lags::Vector{Int}) -> String

Write the first and the last lag, such as `1–10`.
"""
function lag_range_text(lags::Vector{Int})::String
    return "$(first(lags))–$(last(lags))";
end

"""
    write_table(io, title, description, rows, settings) -> Nothing

Write one table of the report: its heading, one sentence about its rows, the table, and the
white-noise bands. A table that could not run shows its `UNAVAILABLE` text instead of rows.
"""
function write_table(io::IO, title::String, description::String, rows, settings::NamedTuple)::Nothing

    # The heading and the sentence about the rows -
    println(io, "## ", title, "\n");
    println(io, description, "\n");

    # A table that could not run -
    if rows isa String
        println(io, rows, "\n");
        return nothing;
    end

    # The columns; the hesitant table also has the steps from flat to long -
    headers = ["Market", "Excess kurtosis",
        "Clustering, lags $(lag_range_text(settings.short_lags))",
        "Clustering, lags $(lag_range_text(settings.long_lags))",
        "Autocorrelation, lag 1", "Volatility (1/sqrt(yr))", "Gap spread"];
    has_steps = haskey(rows[1], :steps);
    if has_steps
        push!(headers, "Steps from flat to long");
    end
    println(io, "| ", join(headers, " | "), " |");
    alignments = fill("--:", length(headers));
    alignments[1] = ":--";
    println(io, "|", join(alignments, "|"), "|");

    # One line per row; kurtosis has 1 decimal and the other numbers have 2 -
    for row in rows
        cells = [row.label, number_text(row.kurtosis, 1), number_text(row.clustering_short, 2),
            number_text(row.clustering_long, 2), number_text(row.lag_one, 2),
            number_text(row.volatility, 2), number_text(row.gap_spread, 2)];
        if has_steps
            push!(cells, number_text(row.steps, 2));
        end
        println(io, "| ", join(cells, " | "), " |");
    end

    # The white-noise bands of the simulated markets and of the benchmark -
    model_band = white_noise_band(settings.number_of_steps);
    benchmark_count = length(benchmark_growth_rates(settings));
    println(io, "\nWhite-noise band of an autocorrelation: ", number_text(model_band, 3),
        " for the simulated markets, ", number_text(white_noise_band(benchmark_count), 3),
        " for ", settings.benchmark_ticker, ".\n");
    return nothing;
end

"""
    write_report(track::String, settings::NamedTuple, path::String) -> Nothing

Run the markets with your functions and write the tables of the report to `path`.

### Arguments

- `track`: `"standard"` (the first table), `"advanced"` (the first two tables), or `"expert"` (all three).
- `settings`: The settings from `load_config`.
- `path`: The Markdown file to write.
"""
function write_report(track::String, settings::NamedTuple, path::String)::Nothing

    # Run the tables of the track; Base.invokelatest lets the report call functions defined after it was loaded -
    standard = Base.invokelatest(standard_table, settings);
    ladders = "";
    if track == "advanced" || track == "expert"
        ladders = Base.invokelatest(ladder_table, settings);
    end
    hesitant = "";
    if track == "expert"
        hesitant = Base.invokelatest(hesitant_table, settings);
    end

    # Write the file: the title, then one table for each table the track runs -
    io = open(path, "w");
    try
        println(io, "# PS6 report\n");

        # The first table, on every track -
        write_table(io, "Farmer–Joshi and SPY",
            "Each simulated row is the mean over $(length(settings.seeds)) runs of $(settings.number_of_steps) daily steps; the gap spread is the standard deviation of the log price minus the log value.",
            standard, settings);

        # The second table, on the Advanced and Expert tracks -
        if track == "advanced" || track == "expert"
            write_table(io, "Conviction ladders",
                "Each row has value investors and trend followers with the listed number of states.",
                ladders, settings);
        end

        # The third table, on the Expert track -
        if track == "expert"
            write_table(io, "Hesitant traders",
                "Each row has traders with $(settings.expert_states) states who act on a proposed move with probability p; the last column is the expected number of steps for a trader to go from flat to long.",
                hesitant, settings);
        end
    finally
        close(io);
    end
    return nothing;
end
